    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Insertion of horizontal and vertical steps", H("Insertion of horizontal and vertical steps"), Blocks(
        Paragraph(Text("All degrees p,q are natural numbers. A shuffle is the monotone injective lattice path defined in ShuffleBasic. To insert a first-coordinate step at face index j, first locate the crossing index t, lift the old first coordinate by j.succAbove, and insert the new vertex at t. The second-coordinate construction exchanges the coordinates.")),
        Paragraph(Text("Deleting the inserted vertex recovers the old path composed with the corresponding coface in the product simplex. The pair consisting of the inserted shuffle and its marked insertion index is injective in the original shuffle and face-index data. The index inequalities include the first and last vertices, so the boundary cases use the same construction.")),
        Describe.Lean(DescribeId.Create("ez-shuffleinsertion-insertleftindex-76f082"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/ShuffleInsertion.insertLeftIndex"), H("insertLeftIndex"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("The vertex index in the `(p+1, q)`-shuffle's domain where the new left step was inserted. Removing this vertex via `δ` recovers the original shuffle. Equals the number of vertices of `ν` whose first coordinate is `< j`.")), Paragraph(Text("In this notation, def insertLeftIndex {p q : ℕ} (ν : Shuffle p q) (j : Fin (p + 2)) : Fin (p + q + 2)."))), DescribeRole.Definition),
