        Describe.Lean(DescribeId.Create("ez-shuffleinsertion-insertrightstep-face-a76d38"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/ShuffleInsertion.insertRightStep_face"), H("insertRightStep_face"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("Inserting a right step and removing the inserted vertex recovers the original shuffle with `Fin.succAbove k` applied to the second coordinate.")), Paragraph(Text("In this notation, lemma insertRightStep_face {p q : ℕ} (ν : Shuffle p q) (k : Fin (q + 2)) : ∀ (i : Index (p + q)), (insertRightStep ν k).1 (Fin.succAbove (⟨(insertRightIndex ν k).val, by omega⟩ : Fin (p + (q + 1) + 1)) (i.cast (by omega))) = ((ν.1 i).1, k.succAbove (ν.1 i).2)."))), DescribeRole.Theorem),
